const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'VAPO: Value-Model-Based RL for Advanced Reasoning'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Accent bar top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: theme.accent }
  });

  // Large stat callout
  slide.addText("60.4", {
    x: 0.5, y: 1.1, w: 9, h: 1.3,
    fontSize: 96, fontFace: "Arial", bold: true,
    color: theme.accent, align: "center", valign: "middle"
  });

  slide.addText("AIME 2024 avg@32", {
    x: 0.5, y: 2.3, w: 9, h: 0.4,
    fontSize: 22, fontFace: "Arial",
    color: theme.light, align: "center", valign: "middle"
  });

  // Main title
  slide.addText("VAPO: Value-Model-Based RL for Advanced Reasoning", {
    x: 0.5, y: 2.9, w: 9, h: 0.9,
    fontSize: 32, fontFace: "Arial", bold: true,
    color: "FFFFFF", align: "center", valign: "middle", wrap: true
  });

  // Subtitle
  slide.addText("Surpassing DAPO by 10+ Points on Long Chain-of-Thought Reasoning", {
    x: 0.5, y: 3.75, w: 9, h: 0.5,
    fontSize: 16, fontFace: "Arial",
    color: "CCCCCC", align: "center", valign: "middle", wrap: true
  });

  // Meta info
  slide.addText("ByteDance Seed  |  Qwen2.5-32B Base  |  No SFT Data", {
    x: 0.5, y: 4.5, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: "999999", align: "center", valign: "middle"
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.55, w: 10, h: 0.08,
    fill: { color: theme.accent }
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "ffc300",
    light: "ffd60a",
    bg: "ffffff"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'VAPO Scores 60 on AIME 2024 — 10+ Points Above DAPO and DeepSeek-R1-Zero'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Arial", bold: true,
    color: theme.primary, align: "left", valign: "middle", wrap: true
  });

  // Bar chart
  const chartData = [{
    name: "AIME 2024 avg@32",
    labels: ["Vanilla PPO", "DeepSeek-R1-Zero\nQwen-32B", "DAPO", "VAPO"],
    values: [5, 47, 50, 60]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.1, w: 5.5, h: 3.6,
    barDir: "col",
    chartColors: [theme.secondary, theme.secondary, theme.secondary, theme.accent],
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    catAxisLabelColor: theme.primary,
    valAxisLabelColor: theme.primary,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 14,
    dataLabelBold: true,
    showLegend: false,
    valAxisMaxVal: 70,
    valAxisMinVal: 0,
    title: "AIME 2024 avg@32 Score",
    titleFontSize: 14,
    titleColor: theme.primary,
    titleBold: true
  });

  // Key stats on right
  const rightX = 6.3;
  const rightW = 3.2;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.1, w: rightW, h: 1.1,
    fill: { color: theme.accent }, rectRadius: 0.03
  });
  slide.addText("+10.4", {
    x: rightX, y: 1.1, w: rightW, h: 0.65,
    fontSize: 40, fontFace: "Arial", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });
  slide.addText("points over DAPO", {
    x: rightX, y: 1.7, w: rightW, h: 0.4,
    fontSize: 13, fontFace: "Arial", bold: false,
    color: theme.primary, align: "center", valign: "middle"
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 2.4, w: rightW, h: 1.1,
    fill: { color: "f5f5f5" }, rectRadius: 0.03
  });
  slide.addText("+13", {
    x: rightX, y: 2.4, w: rightW, h: 0.65,
    fontSize: 40, fontFace: "Arial", bold: true,
    color: theme.secondary, align: "center", valign: "middle"
  });
  slide.addText("points over DeepSeek-R1-Zero", {
    x: rightX, y: 3.0, w: rightW, h: 0.4,
    fontSize: 13, fontFace: "Arial", bold: false,
    color: theme.primary, align: "center", valign: "middle"
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 3.7, w: rightW, h: 1.0,
    fill: { color: "f5f5f5" }, rectRadius: 0.03
  });
  slide.addText("12x", {
    x: rightX, y: 3.7, w: rightW, h: 0.6,
    fontSize: 36, fontFace: "Arial", bold: true,
    color: theme.secondary, align: "center", valign: "middle"
  });
  slide.addText("improvement over Vanilla PPO", {
    x: rightX, y: 4.2, w: rightW, h: 0.4,
    fontSize: 13, fontFace: "Arial", bold: false,
    color: theme.primary, align: "center", valign: "middle"
  });

  // Training curve reference
  slide.addText("Training curve (figure_2.jpg): VAPO reaches ~60% at step 4,500 vs DAPO ~50% at step 5,500", {
    x: 0.5, y: 4.95, w: 9, h: 0.35,
    fontSize: 11, fontFace: "Arial", bold: false,
    color: "666666", align: "left", valign: "middle", italic: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "000814",
    secondary: "001d3d",
    accent: "ffc300",
    light: "ffd60a",
    bg: "ffffff"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'ByteDance Seed';
pres.title = 'VAPO: Value-Model-Based RL for Advanced Reasoning';

const theme = {
  primary: "000814",
  secondary: "001d3d",
  accent: "ffc300",
  light: "ffd60a",
  bg: "ffffff"
};

for (let i = 1; i <= 9; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' });
